parameters.inputSchema:
{
  "title": "Travel office: tasks from one email or message",
  "type": "object",
  "required": [
    "tasks",
    "reasons"
  ],
  "additionalProperties": false,
  "properties": {
    "tasks": {
      "type": "array",
      "description": "The tasks in this email or message. The most important task first.",
      "items": {
        "type": "object",
        "required": [
          "kind",
          "person",
          "event",
          "date",
          "status"
        ],
        "additionalProperties": false,
        "properties": {
          "kind": {
            "type": "string",
            "enum": [
              "trip",
              "leave",
              "estimate",
              "reminder",
              "open_question"
            ]
          },
          "person": {
            "type": "string",
            "description": "Full name of the team member."
          },
          "event": {
            "type": "string",
            "description": "Event name and place, or what the task is about."
          },
          "date": {
            "type": "string",
            "description": "Start date as YYYY-MM-DD, or empty if unknown."
          },
          "status": {
            "type": "string",
            "enum": [
              "open",
              "needs_info",
              "waiting_for_request",
              "ready_to_book",
              "cancelled",
              "done"
            ]
          }
        }
      }
    },
    "reasons": {
      "type": "string",
      "description": "Short explanation of the decision, for the reviewer."
    }
  }
}
